"""JSON parsing and compact, deterministic formatting used by the CLI."""
import json
import math
import re

class JSONError(ValueError):
    pass

def dumps(value):
    if value is None:
        return 'null'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False, separators=(',', ':'))
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            return 'null'
        out = repr(value)
        if 'e' in out:
            mantissa, exponent = out.split('e')
            exp = int(exponent)
            if -5 <= exp < 16:
                # The JSON number writer uses fixed notation in this range.
                out = format(value, '.%df' % max(0, len(mantissa.replace('.', '').replace('-', '')) - 1 - exp))
                if '.' not in out:
                    out += '.0'
            else:
                if mantissa.endswith('.0'):
                    mantissa = mantissa[:-2]
                out = mantissa + 'e' + ('+' if exp >= 0 else '-') + str(abs(exp))
        return out
    if isinstance(value, (list, tuple)):
        return '[' + ','.join(dumps(v) for v in value) + ']'
    if isinstance(value, dict):
        return '{' + ','.join(dumps(k) + ':' + dumps(value[k]) for k in sorted(value)) + '}'
    raise TypeError(type(value).__name__)

class Parser:
    def __init__(self, data):
        self.data = data
        self.i = 0
        self.depth = 0

    def fail(self, message, at=None):
        if at is None:
            at = self.i
        prefix = self.data[:at]
        line = prefix.count('\n') + 1
        col = len(prefix.rsplit('\n', 1)[-1].encode('utf-8', 'surrogatepass'))
        raise JSONError(f'{message} at line {line} column {col}')

    def ws(self):
        while self.i < len(self.data) and self.data[self.i] in ' \t\r\n':
            self.i += 1

    def parse(self):
        result = self.value()
        self.ws()
        if self.i != len(self.data):
            self.fail('trailing characters', self.i + 1)
        return result

    def value(self):
        self.ws()
        if self.i == len(self.data):
            self.fail('EOF while parsing a value')
        c = self.data[self.i]
        if c == '"':
            return self.string()
        if c in '[{':
            self.depth += 1
            if self.depth >= 128:
                self.fail('recursion limit exceeded', self.i + 1)
            self.i += 1
            if c == '[':
                result = self.array()
            else:
                result = self.object()
            self.depth -= 1
            return result
        if c in '-0123456789':
            return self.number()
        for text, value in [('null', None), ('true', True), ('false', False)]:
            if c == text[0]:
                for char in text:
                    if self.i == len(self.data):
                        self.fail('EOF while parsing a value')
                    self.i += 1
                    if self.data[self.i - 1] != char:
                        self.fail('expected ident')
                return value
        self.fail('expected value', self.i + 1)

    def string(self):
        self.i += 1
        result = []
        while True:
            if self.i == len(self.data):
                self.fail('EOF while parsing a string')
            c = self.data[self.i]
            self.i += 1
            if c == '"':
                return ''.join(result)
            if ord(c) < 32:
                self.fail('control character (\\u0000-\\u001F) found while parsing a string')
            if c != '\\':
                if 0xd800 <= ord(c) <= 0xdfff:
                    self.fail('invalid unicode code point')
                result.append(c)
                continue
            if self.i == len(self.data):
                self.fail('EOF while parsing a string')
            c = self.data[self.i]
            self.i += 1
            escapes = {'"':'"', '\\':'\\', '/':'/', 'b':'\b', 'f':'\f', 'n':'\n', 'r':'\r', 't':'\t'}
            if c in escapes:
                result.append(escapes[c])
            elif c == 'u':
                code = self.hex4()
                if 0xd800 <= code <= 0xdbff:
                    if self.i >= len(self.data):
                        self.fail('EOF while parsing a string')
                    if self.data[self.i:self.i+2] != '\\u':
                        self.fail('unexpected end of hex escape', self.i+1)
                    self.i += 2
                    low = self.hex4()
                    if not 0xdc00 <= low <= 0xdfff:
                        self.fail('lone leading surrogate in hex escape')
                    code = 0x10000 + (code - 0xd800) * 1024 + low - 0xdc00
                elif 0xdc00 <= code <= 0xdfff:
                    self.fail('lone leading surrogate in hex escape')
                result.append(chr(code))
            else:
                self.fail('invalid escape')

    def hex4(self):
        out = ''
        for _ in range(4):
            if self.i == len(self.data):
                self.fail('EOF while parsing a string')
            c = self.data[self.i]
            self.i += 1
            if c not in '0123456789abcdefABCDEF':
                self.fail('invalid escape')
            out += c
        return int(out, 16)

    def number(self):
        start = self.i
        if self.data[self.i] == '-':
            self.i += 1
            if self.i == len(self.data):
                self.fail('EOF while parsing a value')
        if self.data[self.i] == '0':
            self.i += 1
            if self.i < len(self.data) and self.data[self.i].isdigit():
                self.fail('invalid number', self.i + 1)
        elif self.data[self.i] in '123456789':
            while self.i < len(self.data) and self.data[self.i] in '0123456789':
                self.i += 1
        else:
            self.fail('invalid number', self.i + 1)
        floating = False
        if self.i < len(self.data) and self.data[self.i] == '.':
            floating = True
            self.i += 1
            if self.i == len(self.data):
                self.fail('EOF while parsing a value')
            if self.data[self.i] not in '0123456789':
                self.fail('invalid number', self.i + 1)
            while self.i < len(self.data) and self.data[self.i] in '0123456789':
                self.i += 1
        if self.i < len(self.data) and self.data[self.i] in 'eE':
            floating = True
            self.i += 1
            if self.i < len(self.data) and self.data[self.i] in '+-':
                self.i += 1
            if self.i == len(self.data):
                self.fail('EOF while parsing a value')
            if self.data[self.i] not in '0123456789':
                self.fail('invalid number', self.i + 1)
            while self.i < len(self.data) and self.data[self.i] in '0123456789':
                self.i += 1
        word = self.data[start:self.i]
        if not floating:
            n = int(word)
            if -(2**63) <= n <= 2**64 - 1 and word != '-0':
                return n
        number = float(word)
        if not math.isfinite(number):
            self.fail('number out of range')
        return number

    def array(self):
        out = []
        self.ws()
        if self.i == len(self.data):
            self.fail('EOF while parsing a list')
        if self.data[self.i] == ']':
            self.i += 1
            return out
        while True:
            out.append(self.value())
            self.ws()
            if self.i == len(self.data):
                self.fail('EOF while parsing a list')
            c = self.data[self.i]
            self.i += 1
            if c == ']':
                return out
            if c != ',':
                self.fail("expected `,` or `]`")
            self.ws()
            if self.i < len(self.data) and self.data[self.i] == ']':
                self.fail('trailing comma', self.i + 1)

    def object(self):
        out = {}
        self.ws()
        if self.i == len(self.data):
            self.fail('EOF while parsing an object')
        if self.data[self.i] == '}':
            self.i += 1
            return out
        while True:
            self.ws()
            if self.i == len(self.data):
                self.fail('EOF while parsing a value')
            if self.data[self.i] != '"':
                self.fail('key must be a string', self.i + 1)
            key = self.string()
            self.ws()
            if self.i == len(self.data):
                self.fail('EOF while parsing an object')
            if self.data[self.i] != ':':
                self.fail('expected `:`', self.i + 1)
            self.i += 1
            out[key] = self.value()
            self.ws()
            if self.i == len(self.data):
                self.fail('EOF while parsing an object')
            c = self.data[self.i]
            self.i += 1
            if c == '}':
                return out
            if c != ',':
                self.fail("expected `,` or `}`")
            self.ws()
            if self.i < len(self.data) and self.data[self.i] == '}':
                self.fail('trailing comma', self.i + 1)

def loads(data):
    if isinstance(data, bytes):
        try:
            data = data.decode('utf-8')
        except UnicodeDecodeError as e:
            raw = data[:e.start]
            line = raw.count(b'\n') + 1
            col = len(raw.rsplit(b'\n', 1)[-1]) + 1
            raise JSONError(f'invalid unicode code point at line {line} column {col}')
    return Parser(data).parse()

def read_json(path):
    with open(path, 'rb') as f:
        return loads(f.read())

def os_error(e):
    return f'{e.strerror} (os error {e.errno})'

def number(v):
    return type(v) in (int, float)

def equal(a, b):
    if number(a) and number(b):
        return a == b
    if type(a) != type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(equal(v, b[k]) for k, v in a.items())
    if isinstance(a, list):
        return len(a) == len(b) and all(equal(x, y) for x, y in zip(a, b))
    return a == b

def unique(items):
    return all(not equal(v, u) for i, v in enumerate(items) for u in items[:i])
PY"}

