        literal = domain[1:-1]
        if literal.lower().startswith('ipv6:'):
            literal = literal[5:]
        try:
            ipaddress.ip_address(literal)
            return True
        except ValueError:
            return False
    return valid_hostname(domain, international)

def check_format(fmt, value):
    if not isinstance(value, str):
        return True
    if fmt == 'regex':
        return regex_valid(value)
    if fmt == 'date':
        return valid_date(value)
    if fmt == 'time':
        return valid_time(value)
    if fmt == 'date-time':
        return len(value) > 10 and value[10] in 'tT' and valid_date(value[:10]) and valid_time(value[11:])
    if fmt in ('email','idn-email'):
        return valid_email(value, fmt == 'idn-email')
    if fmt in ('hostname','idn-hostname'):
        return valid_hostname(value, fmt == 'idn-hostname')
    if fmt in ('ipv4','ipv6'):
        try:
            if '%' in value:
                return False
            return ipaddress.ip_address(value).version == (4 if fmt == 'ipv4' else 6)
        except ValueError:
