        if any(c.isspace() or ord(c) < 32 for c in value):
            return False
        cursor = 0
        while cursor < len(value):
            if value[cursor] == '}':
                return False
            if value[cursor] != '{':
                cursor += 1
                continue
            end = value.find('}', cursor+1)
            if end < 0:
                return False
            expression = value[cursor+1:end]
            if expression[:1] in '+#./;?&':
                expression = expression[1:]
            if not expression:
                return False
            for var in expression.split(','):
                if not re.fullmatch(r'(?:[A-Za-z0-9_.]|%[A-Fa-f0-9]{2})+(?:\*|:[1-9][0-9]{0,3})?', var):
                    return False
            cursor = end+1
        return True
    return True
