def is_type(value, typ, draft=2020):
    if typ == 'null': return value is None
    if typ == 'boolean': return type(value) is bool
    if typ == 'integer': return type(value) is int or (draft != 4 and type(value) is float and value.is_integer())
    if typ == 'number': return number(value)
    if typ == 'object': return isinstance(value, dict)
    if typ == 'array': return isinstance(value, list)
    if typ == 'string': return isinstance(value, str)
    return False

def type_message(value, expected, structured=False):
    if isinstance(expected, str):
        return f'{dumps(value)} is not of type "{expected}"'
    types = sorted(set(expected))
    if len(types) == 1:
        return f'{dumps(value)} is not of type "{types[0]}"'
    if structured:
        return f'{dumps(value)} is not of types (' + ', '.join(types) + ')'
    return f'{dumps(value)} is not of types ' + ', '.join('"'+t+'"' for t in types)

def required_message(name):
    return dumps(name) + ' is a required property'

def unexpected(prefix, names, raw=False):
    words = [dumps(v) if raw else "'" + str(v) + "'" for v in names]
    return prefix + ' (' + ', '.join(words) + (' was unexpected)' if len(words)==1 else ' were unexpected)')

class Node:
    def __init__(self, ep, ip, location, valid=True):
        self.ep = ep
        self.ip = ip
        self.location = location
        self.valid = valid
        self.children = []
        self.errors = {}
        self.text_errors = []
        self.annotation = UNSET
        self.props = set()
        self.items = set()

    def error(self, keyword, message, text=None):
        self.valid = False
        if keyword in self.errors:
            if not isinstance(self.errors[keyword], list):
                self.errors[keyword] = [self.errors[keyword]]
            self.errors[keyword].append(message)
        else:
            self.errors[keyword] = message
        self.text_errors.append(message if text is None else text)
        return self

    def add(self, child, errors=True):
        self.children.append(child)
        self.valid = self.valid and child.valid
        if errors:
            self.text_errors.extend(child.text_errors)
        return child

    def as_dict(self, children=True):
        out = {'valid':self.valid, 'evaluationPath':self.ep, 'instanceLocation':self.ip, 'schemaLocation':self.location}
        if self.errors:
            out['errors'] = self.errors
        if self.annotation is not UNSET:
            out['annotations' if self.valid else 'droppedAnnotations'] = self.annotation
        if children and self.children:
            out['details'] = [n.as_dict() for n in self.children]
        return out

    def flatten(self):
        result = [self.as_dict(False)]
        for ch in self.children:
            result.extend(ch.flatten())
        return result

    def payload(self, mode):
        if mode == 'flag': return {'valid':self.valid}
        if mode == 'list': return {'valid':self.valid, 'details':self.flatten()}
