             'http://json-schema.org/draft-07/schema':7, 'https://json-schema.org/draft/2019-09/schema':2019,
             'https://json-schema.org/draft/2020-12/schema':2020}
    if url in known:
        return known[url]
    return None


def resolve_url(base, reference):
    if re.match(r'^[A-Za-z][A-Za-z0-9+.-]*:', reference):
        return reference
    if reference.startswith('#'):
        return base.split('#')[0] + reference
