        self.base = base
        self.draft = draft
        self.documents = {base.split('#')[0]:schema}
        self.anchors = {}
        self.timeout = timeout
        self.context = context
        self.register(schema, base)

    def register(self, schema, base, depth=0):
        if not isinstance(schema, dict) or depth > 100:
            return
