                    if c.isspace() or ord(c)<32 or c in '<>"{}|\\^`':
                        raise SchemaError(f"Invalid URI reference '{ident}': unexpected character at index {ix}")
                raise SchemaError(f"Invalid URI reference '{ident}': invalid URI")
            newbase = resolve_url(base, ident)
            without, _, frag = newbase.partition('#')
            if frag:
                self.anchors[(without, frag)] = schema
            else:
                self.documents[without] = schema
            base = newbase
        for key in ('$anchor','$dynamicAnchor'):
            if key in schema and isinstance(schema[key], str) and self.draft >= 2019:
                self.anchors[(base.split('#')[0], schema[key])] = schema
        for child in schema.values():
            if isinstance(child, dict):
                # IDs may also appear inside maps of subschemas.
                for sub in child.values():
                    if isinstance(sub, (dict,list)):
                        self._register_value(sub, base, depth+1)
                if any(k in child for k in ('$id','id','$anchor','$dynamicAnchor')):
                    self.register(child, base, depth+1)
            elif isinstance(child, list):
                for sub in child:
                    self._register_value(sub, base, depth+1)

    def _register_value(self, value, base, depth):
        if isinstance(value, dict): self.register(value, base, depth)
        elif isinstance(value, list):
            for sub in value:self._register_value(sub, base, depth+1)

    def retrieve(self, uri):
        scheme = urllib.parse.urlsplit(uri).scheme
