"""An independent JSON Schema evaluator and evaluation-report tree."""
import base64
import math
import os
import re
import ssl
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

from jsonio import dumps, loads, read_json, number, equal, unique, os_error
from formats import KNOWN_FORMATS, check_format, matches, display_pattern, regex_valid, uri_valid

UNSET = object()
TYPES = ('array','boolean','integer','null','number','object','string')
ORDER = ('type','const','enum','minimum','maximum','exclusiveMinimum','exclusiveMaximum','multipleOf',
         'minLength','maxLength','minItems','maxItems','minProperties','maxProperties','required','dependentRequired',
         'pattern','format','contentEncoding','contentMediaType','uniqueItems','properties','patternProperties',
         'additionalProperties','propertyNames','items','prefixItems','additionalItems','contains','dependencies',
         'dependentSchemas','allOf','anyOf','oneOf','not','if','$ref','$recursiveRef','$dynamicRef',
         'unevaluatedItems','unevaluatedProperties')

class SchemaError(Exception):
    def __init__(self, message, meta=False):
        super().__init__(message)
        self.meta = meta


def pointer(path, name):
    return path + '/' + str(name).replace('~','~0').replace('/','~1')

def is_type(value, typ, draft=2020):
    if typ == 'null': return value is None
    if typ == 'boolean': return type(value) is bool
    if typ == 'integer': return type(value) is int or (draft != 4 and type(value) is float and value.is_integer())
    if typ == 'number': return number(value)
    if typ == 'object': return isinstance(value, dict)
    if typ == 'array': return isinstance(value, list)
    if typ == 'string': return isinstance(value, str)
    return False

def type_message(value, expected, structured=False):
    if isinstance(expected, str):
        return f'{dumps(value)} is not of type "{expected}"'
    types = sorted(set(expected))
    if len(types) == 1:
        return f'{dumps(value)} is not of type "{types[0]}"'
    if structured:
        return f'{dumps(value)} is not of types (' + ', '.join(types) + ')'
    return f'{dumps(value)} is not of types ' + ', '.join('"'+t+'"' for t in types)

def required_message(name):
    return dumps(name) + ' is a required property'

def unexpected(prefix, names, raw=False):
    words = [dumps(v) if raw else "'" + str(v) + "'" for v in names]
    return prefix + ' (' + ', '.join(words) + (' was unexpected)' if len(words)==1 else ' were unexpected)')

class Node:
    def __init__(self, ep, ip, location, valid=True):
        self.ep = ep
        self.ip = ip
        self.location = location
        self.valid = valid
        self.children = []
        self.errors = {}
        self.text_errors = []
        self.annotation = UNSET
        self.props = set()
        self.items = set()

    def error(self, keyword, message, text=None):
        self.valid = False
        if keyword in self.errors:
            if not isinstance(self.errors[keyword], list):
                self.errors[keyword] = [self.errors[keyword]]
            self.errors[keyword].append(message)
        else:
            self.errors[keyword] = message
        self.text_errors.append(message if text is None else text)
        return self

    def add(self, child, errors=True):
        self.children.append(child)
        self.valid = self.valid and child.valid
        if errors:
            self.text_errors.extend(child.text_errors)
        return child

    def as_dict(self, children=True):
        out = {'valid':self.valid, 'evaluationPath':self.ep, 'instanceLocation':self.ip, 'schemaLocation':self.location}
        if self.errors:
            out['errors'] = self.errors
        if self.annotation is not UNSET:
            out['annotations' if self.valid else 'droppedAnnotations'] = self.annotation
        if children and self.children:
            out['details'] = [n.as_dict() for n in self.children]
        return out

    def flatten(self):
        result = [self.as_dict(False)]
        for ch in self.children:
            result.extend(ch.flatten())
        return result

    def payload(self, mode):
        if mode == 'flag': return {'valid':self.valid}
        if mode == 'list': return {'valid':self.valid, 'details':self.flatten()}
        return self.as_dict()


def choose_draft(schema, default=2020):
    if not isinstance(schema, dict) or not isinstance(schema.get('$schema'), str):
        return default
    url = schema['$schema'].rstrip('#')
    known = {'http://json-schema.org/draft-04/schema':4, 'http://json-schema.org/draft-06/schema':6,
             'http://json-schema.org/draft-07/schema':7, 'https://json-schema.org/draft/2019-09/schema':2019,
             'https://json-schema.org/draft/2020-12/schema':2020}
    if url in known:
        return known[url]
    return None


def resolve_url(base, reference):
    if re.match(r'^[A-Za-z][A-Za-z0-9+.-]*:', reference):
        return reference
    if reference.startswith('#'):
        return base.split('#')[0] + reference
    if base.startswith('urn:') or base.startswith('json-schema:'):
        if base.startswith('urn:'):
            return urllib.parse.urljoin(base, reference)
        return 'json-schema:///' + reference.lstrip('/')
    return urllib.parse.urljoin(base, reference)

class Registry:
    def __init__(self, schema, base, draft=2020, timeout=None, context=None):
        self.root = schema
        self.base = base
        self.draft = draft
        self.documents = {base.split('#')[0]:schema}
        self.anchors = {}
        self.timeout = timeout
        self.context = context
        self.register(schema, base)

    def register(self, schema, base, depth=0):
        if not isinstance(schema, dict) or depth > 100:
            return
        idkey = 'id' if self.draft == 4 else '$id'
        ident = schema.get(idkey)
        if isinstance(ident, str):
            if not uri_valid(ident, iri=True):
                for ix,c in enumerate(ident):
                    if c.isspace() or ord(c)<32 or c in '<>"{}|\\^`':
                        raise SchemaError(f"Invalid URI reference '{ident}': unexpected character at index {ix}")
                raise SchemaError(f"Invalid URI reference '{ident}': invalid URI")
            newbase = resolve_url(base, ident)
            without, _, frag = newbase.partition('#')
            if frag:
                self.anchors[(without, frag)] = schema
            else:
                self.documents[without] = schema
            base = newbase
        for key in ('$anchor','$dynamicAnchor'):
            if key in schema and isinstance(schema[key], str) and self.draft >= 2019:
                self.anchors[(base.split('#')[0], schema[key])] = schema
        for child in schema.values():
            if isinstance(child, dict):
                # IDs may also appear inside maps of subschemas.
                for sub in child.values():
                    if isinstance(sub, (dict,list)):
                        self._register_value(sub, base, depth+1)
                if any(k in child for k in ('$id','id','$anchor','$dynamicAnchor')):
                    self.register(child, base, depth+1)
            elif isinstance(child, list):
                for sub in child:
                    self._register_value(sub, base, depth+1)

    def _register_value(self, value, base, depth):
        if isinstance(value, dict): self.register(value, base, depth)
        elif isinstance(value, list):
            for sub in value:self._register_value(sub, base, depth+1)

    def retrieve(self, uri):
        scheme = urllib.parse.urlsplit(uri).scheme
        try:
            if scheme == 'file':
                path = urllib.parse.unquote(urllib.parse.urlsplit(uri).path)
                data = read_json(path)
            elif scheme in ('http','https'):
                try:
                    req = urllib.request.Request(uri,headers={'Accept':'*/*'})
                    with urllib.request.urlopen(req, timeout=self.timeout or 15, context=self.context) as f:
                        data = loads(f.read())
                except urllib.error.HTTPError as e:
                    kind = 'client' if e.code < 500 else 'server'
                    raise ValueError(f'HTTP status {kind} error ({e.code} {e.reason}) for url ({uri})')
                except (urllib.error.URLError, TimeoutError, OSError):
                    raise ValueError(f'error sending request for url ({uri})')
            else:
                raise ValueError('Unknown scheme ' + (scheme or 'json-schema'))
        except OSError as e:
            raise SchemaError(f"Resource '{uri}' is not present in a registry and retrieving it failed: {os_error(e)}")
        except (ValueError, SchemaError) as e:
            raise SchemaError(f"Resource '{uri}' is not present in a registry and retrieving it failed: {e}")
        self.documents[uri] = data
        self.register(data, uri)
        return data

    def resolve(self, reference, base):
        if not uri_valid(reference, iri=True):
            bad = next((i for i,c in enumerate(reference) if c.isspace() or ord(c)<32 or c in '<>"{}|\\^`'),0)
            raise SchemaError(f"Invalid URI reference '{reference}': unexpected character at index {bad}")
        url = resolve_url(base, reference)
        doc, _, fragment = url.partition('#')
        fragment = urllib.parse.unquote(fragment)
        if doc not in self.documents:
            self.retrieve(doc)
        target = self.documents[doc]
        sp = ''
        if fragment.startswith('/'):
            sp = fragment
            for word in fragment[1:].split('/'):
                part = word.replace('~1','/').replace('~0','~')
                if isinstance(target, dict) and part in target:
                    target = target[part]
                elif isinstance(target, list) and re.fullmatch(r'0|[1-9][0-9]*',part) and int(part) < len(target):
                    target = target[int(part)]
                else:
                    raise SchemaError(f"Pointer '{fragment}' does not exist")
        elif fragment:
            if (doc, fragment) not in self.anchors:
                raise SchemaError(f"Anchor '{fragment}' does not exist")
            target = self.anchors[(doc, fragment)]
        return target, doc, sp

class Evaluator:
    def __init__(self, schema, base, draft=2020, assert_format=False, registry=None, meta_mode=False):
        self.schema = schema
        self.base = base
        self.draft = draft
        self.assert_format = assert_format
        self.registry = registry if registry is not None else Registry(schema,base,draft)
        self.meta_mode = meta_mode
        self.active = set()

    def evaluate(self, instance):
        return self.eval(self.schema, instance, '', '', self.base, '')

    def eval(self, schema, value, ep, ip, base, sp, scopes=()):
        idkey = 'id' if self.draft == 4 else '$id'
        if isinstance(schema,dict) and isinstance(schema.get(idkey),str):
            base = resolve_url(base,schema[idkey])
        base = base.split('#')[0]
        root = Node(ep,ip,base+'#'+sp)
        if schema is True:
            return root
        if schema is False:
            return root.error('falseSchema','False schema does not allow '+dumps(value))
        if not isinstance(schema,dict):
            return root.error('type',type_message(value,['boolean','object']))
        marker = (id(schema),ip)
        if marker in self.active:
            return root
        self.active.add(marker)
        try:
            if schema.get('$recursiveAnchor') is True or '$dynamicAnchor' in schema:
                scopes = scopes + ((schema,base,sp),)
            return self._object(schema,value,root,ep,ip,base,sp,scopes)
        finally:
            self.active.discard(marker)

    def _object(self, schema, value, root, ep, ip, base, sp, scopes):
        draft = self.draft
        active = set(ORDER)
        if draft == 4:
            active -= {'const','contains','propertyNames','if','contentEncoding','contentMediaType'}
        if draft in (4,6):
            active.discard('if')
        if draft < 2019:
            active -= {'dependentRequired','dependentSchemas','unevaluatedItems','unevaluatedProperties','$recursiveRef','$dynamicRef'}
        if draft != 2019:
            active.discard('$recursiveRef')
        if draft != 2020:
            active -= {'prefixItems','$dynamicRef'}
        if draft >= 2020:
            active.discard('additionalItems')
        if draft >= 2019:
            active -= {'contentEncoding','contentMediaType'}
        recognized = active | {'$schema','then','else','format','additionalProperties'}
        if draft == 4: recognized.add('id')
        else: recognized.add('$id')
        if draft >= 2019: recognized |= {'$defs','$anchor','$recursiveAnchor','minContains','maxContains'}
        if draft == 2020: recognized |= {'$dynamicAnchor','$vocabulary'}
