        def knode(k): return Node(pointer(ep,k),ip,base+'#'+pointer(sp,k))
        def sub(k, sch, val=value, loc=ip, suffix=None):
            sep = pointer(ep,k)
            ssp = pointer(sp,k)
            if suffix is not None:
                sep,ssp=pointer(sep,suffix),pointer(ssp,suffix)
            return self.eval(sch,val,sep,loc,base,ssp,scopes)
        for k in ORDER:
            if k not in active or k not in schema:
