                    root.items.update(range(start,len(value)))
                continue
            if k == 'format' and (not self.assert_format or constraint not in KNOWN_FORMATS):
                continue
            if k == 'if' and 'then' not in schema and 'else' not in schema:
                continue
            if k == 'additionalItems' and not isinstance(schema.get('items'),list):
                continue
            if k == 'additionalItems' and constraint is True:
                continue
            if k == 'contentEncoding' and 'contentMediaType' in schema and schema['contentMediaType']=='application/json':
                continue
            if k in ('contentEncoding','contentMediaType'):
