"""HTTP retrieval using the Python standard library."""
import gzip
import http.client
import socket
import time
import urllib.error
import urllib.request
import zlib

from jsonio import loads


def fetch_json(uri, timeout=None, connect_timeout=None, context=None):
    connect_limit=connect_timeout
    if timeout is not None:
        connect_limit=timeout if connect_limit is None else min(timeout,connect_limit)

    def finish_connect(connection, start):
        remaining=None if timeout is None else max(0,timeout-(time.monotonic()-start))
        if connection.sock is not None:connection.sock.settimeout(remaining)

    class HTTP(http.client.HTTPConnection):
        def __init__(self, host, timeout=None, **kwargs):
            super().__init__(host, timeout=connect_limit, **kwargs)
        def connect(self):
            start=time.monotonic()
            super().connect()
            finish_connect(self,start)

    class HTTPS(http.client.HTTPSConnection):
        def __init__(self, host, timeout=None, **kwargs):
            super().__init__(host, timeout=connect_limit, **kwargs)
        def connect(self):
            start=time.monotonic()
            super().connect()
            finish_connect(self,start)

    class HTTPHandler(urllib.request.HTTPHandler):
        def http_open(self, req):return self.do_open(HTTP,req)

    class HTTPSHandler(urllib.request.HTTPSHandler):
        def https_open(self, req):
            return self.do_open(HTTPS,req,context=self._context,check_hostname=self._check_hostname)

    opener=urllib.request.build_opener(HTTPHandler(),HTTPSHandler(context=context))
    opener.addheaders=[]
    request=urllib.request.Request(uri,headers={'Accept':'*/*'})
    try:
        response=opener.open(request,timeout=connect_limit)
    except urllib.error.HTTPError as e:
        if e.code in (301,302,303,307,308):
            raise ValueError(f'error sending request for url ({uri})')
        response=e
    except (urllib.error.URLError,OSError,ValueError,http.client.HTTPException):
        raise ValueError(f'error sending request for url ({uri})')
    try:
        with response:
            data=response.read()
            encoding=response.headers.get('Content-Encoding','').lower()
            if encoding=='gzip':data=gzip.decompress(data)
            elif encoding=='deflate':data=zlib.decompress(data)
            return loads(data)
    except (ValueError,OSError,http.client.HTTPException,zlib.error):
        raise ValueError(f'error decoding response body for url ({response.geturl()})')
